"""Return singular equivalent POS-tag for given POS-tag."""
def singularize(args: Any, premise: Any) -> object {
    pos = args[0];
    singularize_dict = {
        'NNS': 'NN',
        'NN': 'NN',
        'NNPS': 'NNP',
        'VBP': 'VBZ',
        'VBD': 'VBD',
        'VB': 'VB',
        'VBZ': 'VBZ',
        'VBN': 'VBN',
        'MD': 'MD'
    };
    try {
        sing_pos = singularize_dict[pos];
    } except KeyError {
        return pos;
    }
    return sing_pos;
}

"""flatten results with error

    Args:
        results_with_err ([(Error, result)]): results with error

    Returns:
        (Error, [result]): error, results
    """
def _flatten_results_with_err(results_with_err: Any) -> object {
    err_msg_list = [];
    results = [];
    for (idx, (each_err, each_result)) in enumerate(results_with_err) {
        if each_err {
            err_msg_list.append(
                ('(%s/%s) e: %s' % (idx, len(results_with_err), each_err))
            );
        }
        results.append(each_result);
    }
    err = None if not err_msg_list else Exception(','.join(err_msg_list));
    if err {
        return (err, results);
    }
    return (None, results);
}

"""
    Takes three side lengths an returns the largest
    :param side1: int or float
    :param side2: int or float
    :param side3: int or float
    :return: int or float
    """
def find_c(side1: Any, side2: Any, side3: Any) -> object {
    if ((side1 > side2) and (side1 > side3)) {
        return side1;
    } elif ((side2 > side1) and (side2 > side3)) {
        return side2;
    } elif ((side3 > side2) and (side3 > side1)) {
        return side3;
    }
}

"""
    Checks add_command for "RENAME: <old_name>".
    Returns the value of old_name if there is a match.
    Otherwise returns an empty string.
    """
def get_rename(add_command: Any) -> object {
    if ((add_command is None) or (len(add_command) == 0)) {
        return "";
    }
    s = add_command.strip();
    if s.lower().startswith("rename:") {
        old_name = s.split(":")[1].strip().strip('"').strip("'");
        assert (0 < len(old_name));
        return old_name;
    } else {
        return "";
    }
}

"""
