    """
def init_hash_counters() -> object {
    hash_counters = {};
    hash_count_values = [
        'total samples',
        'malware',
        'mal_inactive_sig',
        'mal_active_sig',
        'mal_no_sig',
        'grayware',
        'benign',
        'phishing',
        'No sample found'
    ];
    for value in hash_count_values {
        hash_counters[value] = 0;
    }
    return hash_counters;
}

